const json = pm.response.json();
const user = json.user;
const decode = s => JSON.parse(atob(
    (s + "=".repeat((4 - s.length % 4) % 4)).replace(/-/g, "+").replace(/_/g, "/")));

pm.test("Status 201 Created", () => pm.response.to.have.status(201));

pm.test("Responde JSON", () =>
    pm.response.to.have.header("Content-Type", "application/json"));

pm.test("Trae los campos requeridos", () => {
    ["id", "created", "modified", "last_login", "token", "isactive"]
        .forEach(k => pm.expect(user, k).to.have.property(k));
});

pm.test("El id es un UUID", () =>
    pm.expect(user.id).to.match(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/));

pm.test("Usuario nuevo: last_login coincide con created y isactive es true", () => {
    pm.expect(user.last_login).to.eql(user.created);
    pm.expect(user.isactive).to.eql(true);
});

pm.test("El token es un JWT con tres partes (firma no vacía)", () =>
    pm.expect(user.token).to.match(/^[\w-]+\.[\w-]+\.[\w-]+$/));

pm.test("El JWT está firmado con HS256 y su sub es el id del usuario", () => {
    const [h, p] = user.token.split(".");
    pm.expect(decode(h).alg).to.eql("HS256");
    pm.expect(decode(p).sub).to.eql(user.id);
    pm.expect(decode(p).exp).to.be.above(decode(p).iat);
});

pm.test("La respuesta no expone la contraseña", () =>
    pm.expect(pm.response.text()).to.not.include("password"));

const mensajeEsperado = "Debe tener al menos un teléfono";

pm.test("Status 400 Bad Request", () => pm.response.to.have.status(400));
pm.test("Responde JSON", () =>
    pm.response.to.have.header("Content-Type", "application/json"));
pm.test(`El cuerpo es exactamente { "mensaje": "${mensajeEsperado}" }`, () =>
    pm.expect(pm.response.json()).to.eql({ mensaje: mensajeEsperado }));

